text:
{{
  (() => {
    const data = Table_Achats.tableData || [];

    const totalAttendu = data.reduce((sum, row) => 
      row.Dans_Carton_En_Cours ? sum + (Number(row.Quantite_BL) || 0) : sum, 0
    );

    const totalScanne = data.reduce((sum, row) => 
      row.Dans_Carton_En_Cours ? sum + (Number(row.Livraison_Du_Jour) || 0) : sum, 0
    );

    // Si le total scanné atteint ou dépasse le total attendu
    if (totalAttendu > 0 && totalScanne >= totalAttendu) {
      return `✅ CARTON COMPLET : ${totalScanne} / ${totalAttendu} pièce(s)`;
    }

    // Sinon, on affiche la progression normale
    return `📊 PROGRESSION SCAN : ${totalScanne} / ${totalAttendu} pièce(s)`;
  })()
}}

textColor:
{{
  (() => {
    const data = Table_Achats.tableData || [];
    const totalAttendu = data.reduce((sum, row) => row.Dans_Carton_En_Cours ? sum + (Number(row.Quantite_BL) || 0) : sum, 0);
    const totalScanne = data.reduce((sum, row) => row.Dans_Carton_En_Cours ? sum + (Number(row.Livraison_Du_Jour) || 0) : sum, 0);

    return (totalAttendu > 0 && totalScanne >= totalAttendu) ? "#059669" : "#000000";
  })()
}}
